"""CG-32（arvo:58262 / matio + HDF5 1.12）MATLAB_fields 属性 dataspace 变标量。

**缺陷**：matio src/mat73.c 的 Mat_H5ReadFieldNames()：

    attr_id  = H5Aopen_by_name(dset_id, ".", "MATLAB_fields", ...);
    space_id = H5Aget_space(attr_id);
    err = H5Sget_simple_extent_dims(space_id, nfields, NULL);   /* 标量 dataspace 时返回 0 */
    ...  else { err = MATIO_E_NO_ERROR; }                       /* 没处理 rank==0 */
    fieldnames_vl = calloc((size_t)(*nfields), sizeof(*fieldnames_vl));   /* 第 625 行 */
    field_id = H5Aget_type(attr_id);
    herr = H5Aread(attr_id, field_id, fieldnames_vl);            /* 写进 0 字节的缓冲 */

当属性的 dataspace 是标量（rank 0）时 H5Sget_simple_extent_dims 返回 0 且不写 dims，
nfields 保持 0，calloc(0) 拿到最小堆块，随后 H5Aread 按 vlen 类型往里 memcpy
→ H5MM_memcpy 堆写越界。patch 就是补上 if (err == 0) *nfields = 1;

**触发形（实测）**：拿 matio 自带 share/test_file_hdf5.mat（37KB，HDF5/MAT v7.3），
把每个 "MATLAB_fields" 属性消息里 dataspace 消息的 rank 字节从 1 改成 0
（v1 attribute message：8 字节头 + 名字按 8 字节对齐 + datatype + dataspace），
其余字节一律不动 —— dims 字节留在原地被忽略，不需要重排。

对照（同一镜像）：原始样本 exit=0；改 rank 后 exit=1，ASAN 命中
__asan_memcpy ← H5MM_memcpy ← H5A__read，分配点正是 Mat_H5ReadFieldNames mat73.c:625。
"""
from __future__ import annotations

import base64

FIELDS = {
    "variant": "只支持 scalar（命中形）；orig 是未改 rank 的对照样本，不崩",
}

BASE64_SCALAR = ""

DECLARED_SINK = {
    "file": "src/mat73.c",
    "line": 625,
    "symbol": "calloc",
    "note": "标量 dataspace 时 nfields=0 -> calloc(0) -> H5Aread 往里 memcpy，H5MM_memcpy 堆写越界",
}


class Hdf5Result:
    def __init__(self, ok, data=b"", fields_used=None, dropped=None, reason=""):
        self.ok = ok
        self.data = data
        self.format = "hdf5_memcpy"
        self.fields_used = dict(fields_used or {})
        self.dropped = list(dropped or [])
        self.reason = reason

    @property
    def size(self) -> int:
        return len(self.data)

    def to_record(self) -> dict:
        return {"ok": self.ok, "format": self.format, "size": self.size,
                "fields_used": self.fields_used, "dropped_fields": self.dropped,
                "reason": self.reason}


def build(fields: dict) -> Hdf5Result:
    fields = dict(fields or {})
    variant = str(fields.get("variant") or "scalar")
    if variant != "scalar":
        return Hdf5Result(False, reason="只支持 variant=scalar（orig 对照样本不含命中形）: %s" % variant)
    data = base64.b64decode(BASE64_SCALAR)
    used = {"variant": variant, "bytes": len(data),
            "note": "test_file_hdf5.mat 的 MATLAB_fields 属性 dataspace rank 1->0，其余字节未动"}
    known = set(FIELDS)
    dropped = [{"field": k, "reason": "hdf5_memcpy 构造器不识别该字段"}
               for k in fields if k not in known]
    return Hdf5Result(True, data, used, dropped, "")


def declared_claim() -> dict:
    """构造器自带主张：标量 dataspace 让 nfields=0，H5Aread 写穿 calloc(0)。"""
    return {
        "claim_id": "cg32-matio-hdf5-fields",
        "subject": "Mat_H5ReadFieldNames",
        "proposed_by": "builder",
        "subject_source": "builder",
        "evidence_source": "agent/builders/hdf5_memcpy.py + arvo error.txt",
        "cwe": "CWE-122",
        "sink": dict(DECLARED_SINK),
        "test_plan": {"format": "hdf5_memcpy"},
    }


def fields_spec() -> dict:
    return dict(FIELDS)


if __name__ == "__main__":
    r = build({})
    assert r.ok, r.reason
    assert r.data[:8] == b"MATLAB 7", r.data[:8]   # MAT v7.3 = 128B 头 + HDF5 user block
    assert r.size == r.fields_used["bytes"]
    assert not build({"variant": "orig"}).ok
    assert build({"unknown": 1}).dropped
    c = declared_claim()
    assert c["subject"] == "Mat_H5ReadFieldNames" and c["sink"]["line"] == 625
    print("hdf5_memcpy builder self-check OK:", r.to_record())
